import{c as t,Q as n,j as o,m as a}from"./chunks/framework.g_l1frA7.js";const u=JSON.parse('{"title":"Emergency Fund","description":"","frontmatter":{},"headers":[],"relativePath":"framework/emergency-fund.md","filePath":"framework/emergency-fund.md","lastUpdated":null}'),r={name:"framework/emergency-fund.md"};function i(s,e,l,c,d,h){return n(),o("div",null,[...e[0]||(e[0]=[a('<h1 id="emergency-fund" tabindex="-1">Emergency Fund <a class="header-anchor" href="#emergency-fund" aria-label="Permalink to &quot;Emergency Fund&quot;">​</a></h1><blockquote><p>3–6 months of expenses, saved before ambitious plans. — <em>Ramsey</em> / <em>Sethi</em></p></blockquote><h2 id="the-metric" tabindex="-1">The metric <a class="header-anchor" href="#the-metric" aria-label="Permalink to &quot;The metric&quot;">​</a></h2><p><code>emergency_fund_months = total_balance / average_monthly_expenses</code></p><p>Computed in <code>wellness_context</code> from your ledger. A reliability flag suppresses the headline when history is thin — a brand-new user with nine months of cover from a one-time balance is shown as provisional.</p><h2 id="using-it" tabindex="-1">Using it <a class="header-anchor" href="#using-it" aria-label="Permalink to &quot;Using it&quot;">​</a></h2><ul><li><strong>Goals → Emergency fund</strong> — quick-fill computes the shortfall to the next month of cover and creates a contribution in one tap.</li><li><strong>Today → Progress disclosure</strong> — the milestone card shows months of cover and the inputs behind it.</li><li><strong>Copilot</strong> — “How long until my emergency fund is full at $400/month?” runs the contribution projection and cites the months.</li></ul><h2 id="policy" tabindex="-1">Policy <a class="header-anchor" href="#policy" aria-label="Permalink to &quot;Policy&quot;">​</a></h2><p>FinSight does not treat the emergency fund as a category — it is a goal funded from Saving envelopes. Fund it first; the Copilot ranks it above debt payoff only when debt is non-urgent, and the prompt encodes that ordering.</p><p>Typical order: stability → one month → three–six months → debt payoff → compounding.</p>',10)])])}const p=t(r,[["render",i]]);export{u as __pageData,p as default};
